{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Lu 25-109, which shares the N-methyltetrahydropyridine-heteroaryl core, entered brain in a 1:1 ratio with blood in rat microdialysis, directly supporting meaningful CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "CI-979, another N-methyltetrahydropyridine-containing muscarinic agonist, rapidly entered monkey brain with 5-10% of the intravenous dose reaching the brain by PET, supporting CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "The desethyl tetrazole analogue Lu 31-126 was not detected in rat brain microdialysis, but its acidic tetrazole and loss of the lipophilic substituent make it a weaker transfer model for the lipophilic hexyloxy-thiadiazole query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogue Lu 25-109 shows 1:1 brain:blood penetration in rat microdialysis, and CI-979 shows high brain uptake in monkey PET; the query shares the N-methyltetrahydropyridine and heteroaromatic core. The contradictory desethyl-tetrazole analogue is much more polar/acidic and less transferable. Overall, meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct brain/plasma, CSF, or PET measurement exists for the query molecule itself.",
    "Efflux transporter (P-gp/BCRP) susceptibility of the query is inferred only from the basic amine and not experimentally confirmed.",
    "The closest evidence is from analogues with moderate Morgan similarity (0.37), not exact matches."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

